<?php require_once '../config/database.php'; require_once '../includes/functions.php'; $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $stmt=$pdo->prepare('SELECT * FROM users WHERE email=? AND role="admin"'); $stmt->execute([trim($_POST['email']??'')]); $admin=$stmt->fetch(); if($admin && password_verify($_POST['password']??'', $admin['password'])){ $_SESSION['admin']=['id'=>$admin['id'],'name'=>$admin['name']]; redirect('dashboard.php'); } $error='Invalid admin email or password.'; } ?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Admin Login | FoodNest</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="form-shell"><h1>Admin login</h1><p class="muted">FoodNest management area.</p><?php if($error): ?><p class="error"><?= esc($error) ?></p><?php endif; ?><form method="post"><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button type="submit">Login</button></form><p><a class="text-link" href="../index.php">Back to website</a></p></div></body></html>